INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Huling Pasada', 'Huling Pasada', 'huling-pasada-2008', 'The story follows the creative process of Ruby, a prolific writer, abandoned wife and protective mother. She writes about Mario, a taxi driver who becomes a father figure to a street child in the hustle and bustle of the metropolis. As Ruby tries to resolve the story of Mario and the child, she seeks refuge in her own creative output: the line between reality and fiction is blurred, and her character’s past is entangled with her own inevitable future.', '2008-01-01', 2008, 'assets/pasada.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
